<?php declare(strict_types=1); namespace App\Modules\Tourism\Models; use App\Core\Database; final class TourismTrip{private Database $db;public function __construct(){$this->db=app()->get("db");}public function all(int $t):array{return $this->db->fetchAll("SELECT tp.*,u.name user_name,(SELECT COUNT(*) FROM tourism_trip_plan_items i WHERE i.trip_plan_id=tp.id) item_count FROM tourism_trip_plans tp LEFT JOIN users u ON u.id=tp.user_id WHERE tp.tenant_id=? ORDER BY tp.id DESC",[$t]);}}
